"""Standalone interactive GKM graph and exact bounded calculation results."""
import json
from pathlib import Path

out=Path('results/grassmannian-complete-intersections/2026-11-06')
data={name:json.loads((out/(name+'.json')).read_text()) for name in ('catalog','ordinary-cy3-gw','genus-zero-cy3-gw','union-summary')}
html=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{color-scheme:light dark}*{box-sizing:border-box}body{margin:0;color:var(--foreground);font-family:var(--font-sans,system-ui);font-size:14px;line-height:1.5}button,select{font:inherit;color:var(--foreground);background:var(--secondary);border:1px solid var(--border);border-radius:8px;padding:7px 10px}button{cursor:pointer}button.active{border-color:var(--primary);color:var(--primary)}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px}.panel{padding:16px;border-radius:var(--radius,12px);background:var(--card);margin-bottom:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}h3{margin:0 0 8px;font-size:16px}p{margin:8px 0}.muted{color:var(--muted-foreground)}svg{width:100%;height:278px;display:block}.edge{stroke:var(--border);stroke-width:1.5}.edge.hot{stroke:var(--chart-1);stroke-width:2.5}.node circle{fill:var(--secondary);stroke:var(--border);stroke-width:1.5}.node.selected circle{fill:var(--primary);stroke:var(--primary)}.node text{fill:var(--foreground);font:12px var(--font-mono,monospace);text-anchor:middle;dominant-baseline:middle}.node.selected text{fill:var(--primary-foreground)}.node{cursor:pointer}.numbers{display:grid;grid-template-columns:1fr 1fr;gap:10px}.number{background:var(--secondary);padding:10px;border-radius:8px}.value{font-family:var(--font-mono,monospace);font-size:17px;overflow-wrap:anywhere}.label{font-size:12px;color:var(--muted-foreground)}.barrow{display:grid;grid-template-columns:154px 1fr 36px;gap:8px;align-items:center;margin:9px 0}.track{height:18px;background:var(--secondary);border-radius:4px;overflow:hidden}.fill{height:100%;background:var(--chart-1)}.prior{background:var(--chart-2)}.small{font-size:12px}@media(max-width:540px){.grid{grid-template-columns:1fr}svg{height:250px}.barrow{grid-template-columns:120px 1fr 30px}}
</style></head><body>
<div class="controls"><button id="n4" class="active" onclick="chooseAmbient(4)">Gr(2,4)</button><button id="n5" onclick="chooseAmbient(5)">Gr(2,5)</button><span class="muted" style="align-self:center">Non-toric homogeneous ambients</span></div>
<div class="panel grid"><div><h3 id="ambientTitle"></h3><svg id="graph" viewBox="0 0 300 278" aria-label="Grassmannian GKM graph"></svg><div class="small muted">Select a coordinate plane to highlight its invariant lines.</div></div><div><h3>Geometry behind the graph</h3><p id="geometry"></p><p>Vertices are coordinate 2-planes ⟨eᵢ,eⱼ⟩. An edge changes one coordinate and represents a projective line.</p><p id="selected"></p><p class="small muted">Every edge has Plücker degree 1. Edge labels determine tangent weights; the normal splitting supplies the remaining localization factors.</p></div></div>
<div class="panel"><h3>Exact calculated coefficients</h3><div class="controls"><select id="target" onchange="updateValues()" aria-label="Complete intersection"></select><select id="genus" onchange="updateValues()" aria-label="Map genus"><option value="3">Genus 3</option><option value="2">Genus 2</option></select><select id="degree" onchange="updateValues()" aria-label="Plucker degree"><option value="1">Degree 1</option><option value="2">Degree 2</option><option value="0">Degree 0</option></select></div><div id="targetInfo" class="muted"></div><div class="numbers" style="margin-top:12px"><div class="number"><div class="label">Ambient twisted top integral ∫Z</div><div class="value" id="twisted"></div></div><div class="number"><div class="label">Ordinary target GW number N</div><div class="value" id="ordinary"></div></div><div class="number"><div class="label">Infinity aggregate top integral ∫B</div><div class="value" id="infinity"></div></div><div class="number"><div class="label">Ordinary genus-zero N₀,D</div><div class="value" id="genusZero"></div></div></div><p class="small muted" id="status"></p></div>
<div class="panel"><h3>Independent relation vectors across both genera</h3><div class="barrow"><span>Grassmannian search</span><div class="track"><div class="fill" style="width:44.49%"></div></div><b>206</b></div><div class="barrow"><span>Previous toric search</span><div class="track"><div class="fill" style="width:44.49%"></div></div><b>206</b></div><div class="barrow"><span>Previous projective</span><div class="track"><div class="fill prior" style="width:100%"></div></div><b>463</b></div><p class="small muted">The two 206-dimensional spans are equal, with exact certificates. Both lie in the previous 463-dimensional projective span and in Pixton. Degree bound: 2 for Grassmannian/toric, 3 for the previous projective search.</p></div>
<script>const DATA=__DATA__;let n=4,selected=0;const $=s=>document.getElementById(s);function chooseAmbient(value){n=value;selected=0;$('n4').classList.toggle('active',n===4);$('n5').classList.toggle('active',n===5);$('target').innerHTML=DATA.catalog.filter(s=>s.target.ambient.n===n).map(s=>`<option value="${s.target.id}" ${s.target.id===(n===4?'G4':'G11')?'selected':''}>${s.target.id}: [${s.target.degrees.join(',')}] · ${s.target.kind}</option>`).join('');draw();updateValues()}
function draw(){const pts=[];for(let i=1;i<=n;i++)for(let j=i+1;j<=n;j++)pts.push([i,j]);const positions=pts.map((p,i)=>[150+112*Math.cos(2*Math.PI*i/pts.length-Math.PI/2),139+110*Math.sin(2*Math.PI*i/pts.length-Math.PI/2)]);let lines='';for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++)if(pts[i].some(x=>pts[j].includes(x)))lines+=`<line class="edge ${i===selected||j===selected?'hot':''}" x1="${positions[i][0]}" y1="${positions[i][1]}" x2="${positions[j][0]}" y2="${positions[j][1]}"/>`;$('graph').innerHTML=lines+pts.map((p,i)=>`<g class="node ${i===selected?'selected':''}" role="button" tabindex="0" aria-label="Coordinate plane ${p.join(',')}" onclick="selected=${i};draw()" onkeydown="if(event.key==='Enter'){selected=${i};draw()}" transform="translate(${positions[i].join(',')})"><circle r="19"/><text>${p.join('')}</text></g>`).join('');$('ambientTitle').textContent=`Gr(2,${n}): ${pts.length} fixed points, ${n===4?12:30} invariant lines`;$('geometry').textContent=n===4?'A smooth quadric fourfold in P⁵. It parameterizes lines in P³. Its Plücker degree is 2.':'A sixfold in P⁹ defined by five quadratic Plücker relations. It parameterizes lines in P⁴. Its Plücker degree is 5.';const [i,j]=pts[selected];$('selected').textContent=`At ⟨e${i},e${j}⟩, tangent weights are λₖ−λ${i} and λₖ−λ${j} for k outside {${i},${j}}. Along an invariant line, N = O(1)^${n-2} ⊕ O^${n-3}.`}
function negate(s){return s==='0'?'0':s.startsWith('-')?s.slice(1):'-'+s}
function updateValues(){const id=$('target').value,g=+$('genus').value,d=+$('degree').value,s=DATA.catalog.find(x=>x.target.id===id),t=s.target,z=s.genera.find(x=>x.genus===g).top_twisted_integrals[String(d)],ordinary=DATA['ordinary-cy3-gw'].find(x=>x.target===id&&x.genus===g&&x.beta[0]===d),zero=DATA['genus-zero-cy3-gw'].find(x=>x.target===id&&x.beta[0]===d),alpha=t.dimension*(g-1)-t.c1[0]*d,power=alpha-(3*g-3);$('targetInfo').textContent=`Dimension ${t.dimension} · Plücker degree ${t.pluecker_degree} · Euler characteristic ${t.chern_numbers.euler} · top t exponent ${power}`;$('twisted').textContent=z;$('ordinary').textContent=ordinary?ordinary.ordinary_gw:t.kind==='K3'?'0':'Not determined';$('infinity').textContent=ordinary?ordinary.infinity_aggregate_integral:t.kind==='K3'||power<0?negate(z):'Not determined';$('genusZero').textContent=zero?zero.ordinary_gw:'Not computed here';$('status').textContent=t.kind==='CY3'&&d===2?'The ambient value is known. The ordinary higher-genus degree-two invariant remains undetermined; the genus-zero number does not determine it.':t.kind==='K3'?'Ordinary K3 virtual classes vanish. These are not reduced K3 invariants.':'∫B is the full CJR infinity aggregate, not an individual punctured vertex invariant.'}
chooseAmbient(4);</script></body></html>'''
(out/'grassmannian-explorer.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))))
